import numpy as np
from collections import deque
def exterior(g):
    H,W=g.shape
    reach=np.zeros((H,W),bool); dq=deque()
    for i in range(H):
        for j in (0,W-1):
            if g[i,j]==0: reach[i,j]=True; dq.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i,j]==0: reach[i,j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<H and 0<=b<W and g[a,b]==0 and not reach[a,b]:
                reach[a,b]=True; dq.append((a,b))
    return reach
def solve2(g, ring_for_holeless=False):
    g=np.array(g); H,W=g.shape
    reach=exterior(g)
    from scipy import ndimage
    lab,n=ndimage.label(g==1)
    has_hole={}
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        hole=False
        for a,b in zip(ys,xs):
            for di in (-1,0,1):
                for dj in (-1,0,1):
                    y,x=a+di,b+dj
                    if 0<=y<H and 0<=x<W and g[y,x]==0 and not reach[y,x]: hole=True
        has_hole[i]=hole
    out=g.copy()
    for i in range(H):
        for j in range(W):
            if g[i,j]==0:
                adjt=set()
                for di in (-1,0,1):
                    for dj in (-1,0,1):
                        a,b=i+di,j+dj
                        if 0<=a<H and 0<=b<W and g[a,b]==1: adjt.add(lab[a,b])
                if not adjt: continue
                if any(has_hole[c] for c in adjt) or (ring_for_holeless and not reach[i,j]):
                    out[i,j]= 2 if reach[i,j] else 3
    return out
